class ValidationError(Exception):
    pass

def parse_age(text):
    try:
        age = int(text)
    except ValueError as e:
        raise ValidationError(f"{text!r} is not a number") from e
    else:
        if age < 0:
            raise ValidationError("age cannot be negative")
        return age
    finally:
        print("checked", repr(text))

for raw in ["25", "abc", "-4"]:
    try:
        print("age:", parse_age(raw))
    except ValidationError as err:
        print("invalid:", err, "| cause:", type(err.__cause__).__name__)

